insert into public.settings (key, value, is_public) values ('site', '{"name":"Nilofar Villa Melaka","tagline":"Banglo mewah berinspirasikan French-European untuk percutian keluarga","location":"Bemban, Jasin, Melaka. Bersempadan dengan Ayer Keroh, 8 hingga 10 minit dari Plaza Tol Ayer Keroh.","intro":"Banglo 1.5 tingkat berkonsepkan Luxury dan Modern English dengan 5 bilik, kolam renang peribadi berair terjun dan ruang yang luas untuk seisi keluarga. Semuanya serba baru dan cantik.","checkin_time":"3.00 petang","checkout_time":"12.00 tengah hari","capacity_ideal":15,"capacity_max":20,"pool":"Kolam renang peribadi dengan air terjun, 18 x 7 kaki, dalam 4 kaki","updated_note":"Kemas kini 14 Okt 2026"}'::jsonb, true) on conflict (key) do nothing;
insert into public.settings (key, value, is_public) values ('prices', '{"weekday":{"one":800,"two":1500,"extra":700},"weekend":{"one":1200,"two":2200,"extra":1000},"deposit_standard":300,"deposit_event":500,"late_checkout_per_hour":60,"late_checkout_until":"6.00 petang","full_payment_days_before":3,"cancel_days_before":28,"last_minute_days":3}'::jsonb, true) on conflict (key) do nothing;
insert into public.settings (key, value, is_public) values ('contacts', '{"whatsapp":[{"name":"En. Elyes","phone":"60192656756"},{"name":"Pn. Yati","phone":"60162482289"}],"facebook":"https://www.facebook.com/search/top?q=Homestay%20Nilofar%20Villa%20Melaka","instagram":"https://www.instagram.com/explore/search/keyword/?q=Nilofar%20Villa%20Melaka","tiktok":"https://www.tiktok.com/@yatimajid23","google_maps":"https://share.google/SVV7t2IjF3wPqDS7I"}'::jsonb, true) on conflict (key) do nothing;
insert into public.settings (key, value, is_public) values ('content', '{"rooms":[{"name":"Bilik 1","bed":"1 katil King","features":"Tingkat atas. Kipas, aircond dan bilik air sendiri"},{"name":"Bilik 2","bed":"1 katil King","features":"Kipas, aircond dan bilik air sendiri"},{"name":"Bilik 3","bed":"1 katil Queen","features":"Kipas dan aircond"},{"name":"Bilik 4","bed":"1 katil Queen","features":"Kipas dan aircond"},{"name":"Bilik 5","bed":"1 katil Queen","features":"Kipas, aircond dan bilik air sendiri"}],"facilities":[{"group":"Ruang tamu","items":["2 aircond","Smart TV 55 inci","Karaoke TV dan movie Jazpiper 2.0","Internet Unifi","Sofa selesa"]},{"group":"Dapur dan ruang makan","items":["Kabinet dapur gaya English","Dapur berdiri dengan oven","Peti ais besar 2 pintu","Pinggan, mangkuk, cawan, sudu, garfu, senduk dan sudip","Penapis air Coway","Periuk nasi, pengukus, periuk dan kuali"]},{"group":"Dobi","items":["Mesin basuh dan pengering","Ampaian"]},{"group":"Kemudahan lain","items":["Kolam renang peribadi dengan air terjun","Set BBQ percuma, kipas dan penyepit (arang tidak disediakan)","Ruang tamu tingkat atas","Seterika dan papan seterika","10 helai tuala dan 20 biji bantal","Chandelier dan lampu 3 warna di ruang tamu dan semua bilik"]}],"attractions":[{"time":"4 min","name":"Orna Golf Resort"},{"time":"4 min","name":"Tiara Golf & Country Resort"},{"time":"4 min","name":"Adam & Hawa Wedding Hall"},{"time":"5 min","name":"Mydin Jasin & Bandar Jasin Bistari"},{"time":"5 min","name":"Kolam Air Panas Jasin"},{"time":"8-10 min","name":"Masjid Al-Alami MITC"},{"time":"8-10 min","name":"Dewan Besar MITC"},{"time":"10 min","name":"Taman Buaya Ayer Keroh"},{"time":"10 min","name":"Zoo & Night Zoo Melaka"},{"time":"10 min","name":"Tasik Ayer Keroh (Flyboard Melaka)"},{"time":"10 min","name":"Botanical Garden Melaka"},{"time":"10 min","name":"Taman Mini Malaysia"},{"time":"10 min","name":"Melaka Wonderland Theme Park"},{"time":"13 min","name":"Butterfly Farm"},{"time":"25 min","name":"Lapangan Terbang Batu Berendam"}],"campuses":[{"time":"10 min","name":"Kolej Yayasan Saad"},{"time":"15 min","name":"UTeM"},{"time":"19 min","name":"MMU"}],"food":[{"time":"7 min","name":"KAS Beriani Jasin Bestari"},{"time":"7 min","name":"Asam Pedas Pak Man Bukit Katil"},{"time":"13 min","name":"Yong Tau Fu Tun Teja Bukit Katil"},{"time":"14 min","name":"Pizza Love Melaka"},{"time":"14 min","name":"Char Kuey Teow Warung Kak Bel, Bukit Katil"},{"time":"17 min","name":"Az Rishah Asam Pedas Lipat Kajang"},{"time":"30 min","name":"Cafe Markisa Tasik Chin Chin"},{"time":"31 min","name":"Ikan Bakar Arena, Umbai"}],"beaches":[{"name":"Pantai Siring","description":"Popular untuk makan-makan, healing dan cari ikan segar waktu pagi."},{"name":"Pantai Klebang","description":"Meriah malam hujung minggu dengan pelbagai jualan, dan dekat dengan lokasi aktiviti lasak."}],"beach_drive":"Kira-kira 30 hingga 45 minit memandu","faq":[{"q":"Pukul berapa check in dan check out?","a":"Check in 3.00 petang dan check out 12.00 tengah hari. Lewat check out RM60 sejam sehingga 6.00 petang, bergantung pada kekosongan."},{"q":"Berapa deposit untuk tempahan?","a":"Deposit keselamatan RM300. Untuk majlis ringkas seperti pertunangan atau akikah yang menjemput orang luar, deposit RM500. Deposit dipulangkan dalam 24 jam selepas check out jika tiada kerosakan."},{"q":"Bila perlu bayar penuh?","a":"Bayaran penuh perlu dijelaskan selewat-lewatnya 3 hari sebelum check in."},{"q":"Boleh batal atau tukar tarikh?","a":"Boleh, dengan makluman sekurang-kurangnya 4 minggu sebelum check in. Kurang dari itu deposit tidak dipulangkan, kecuali kecemasan atau kematian yang boleh dibincang."},{"q":"Berapa ramai boleh menginap?","a":"Jumlah ideal 15 orang dan maksimum 20 orang."},{"q":"Ada minimum malam?","a":"Hujung minggu minimum 2 malam, kecuali tempahan saat akhir dan hari bekerja."}]}'::jsonb, true) on conflict (key) do nothing;
insert into public.settings (key, value, is_public) values ('rules', '{"house":["Dilarang membawa makanan tidak halal, alkohol dan bahan terlarang.","Dilarang membawa haiwan peliharaan.","Menghormati hak jiran.","Menggunakan peralatan dan kemudahan homestay dengan cermat.","Menjaga kebersihan homestay."],"policies":["Tetamu mestilah ahli keluarga yang mempunyai hubungan mahram atau kumpulan rakan sama jantina. Percampuran lelaki dan wanita bukan mahram tidak dibenarkan.","Kolam sedalam 4 kaki tanpa lifeguard. Kanak-kanak mesti diawasi orang dewasa dan memakai pelampung.","Wajib memakai pakaian renang atau t-shirt jenis jersey di kolam. Kain, seluar atau t-shirt cotton tidak dibenarkan.","Caj kerosakan atau kehilangan akan ditolak daripada deposit keselamatan.","Pembatalan atau tukar tarikh mesti dimaklumkan sekurang-kurangnya 4 minggu sebelum check in."]}'::jsonb, true) on conflict (key) do nothing;
insert into public.settings (key, value, is_public) values ('bank', '{"bank":"Bank Islam","holder":"Elyes bin Ismail","account":"12186020125808"}'::jsonb, false) on conflict (key) do nothing;
insert into public.settings (key, value, is_public) values ('templates', '{"availability_reply":"Assalamualaikum {nama}. Terima kasih berminat dengan Nilofar Villa Melaka. Tuan/Puan boleh maklumkan tarikh untuk kami semak kekosongan homestay.","confirm":"Assalamualaikum {nama}. Alhamdulillah, tarikh {checkin} hingga {checkout} ({malam} malam) masih kosong untuk Nilofar Villa Melaka.\n\nHarga: RM{jumlah}\nDeposit keselamatan: RM{deposit}\n\nSila transfer deposit ke:\n{bank}\n{akaun}\n{pemegang}\n\nNo. rujukan: {ref}. Terima kasih.","registration":"Assalamualaikum {nama}. Mohon lengkapkan borang pendaftaran penginapan di pautan ini supaya kami boleh sahkan tempahan {ref}:\n{pautan}\n\nSila lampirkan resit deposit RM{deposit}. Terima kasih.","reminder":"Assalamualaikum {nama}. Peringatan mesra untuk tempahan {ref} ({checkin} hingga {checkout}). Baki bayaran RM{baki} perlu dijelaskan sebelum {tarikh_akhir}.\n\n{bank}\n{akaun}\n{pemegang}\n\nTerima kasih.","checkin":"Assalamualaikum {nama}. Selamat datang ke Nilofar Villa Melaka!\n\nCheck in: {checkin}, {masa_checkin}\nCheck out: {checkout}, {masa_checkout}\nLokasi: {peta}\n\nSila patuhi peraturan rumah dan awasi kanak-kanak di kolam. Selamat bercuti!","thanks":"Terima kasih {nama} kerana menginap di Nilofar Villa Melaka. Semoga percutian keluarga menyeronokkan. Deposit akan dipulangkan dalam 24 jam jika semuanya baik. Jemput follow kami di TikTok dan Facebook, dan datang lagi!"}'::jsonb, false) on conflict (key) do nothing;
